
-- SAILING MariaDB schema. 신규 DB에서는 먼저 실행하세요.
-- 기존 USERS / USER_INFO / COMPANY_INFO / STORE_INFO가 있어도 CREATE IF NOT EXISTS는 기존 테이블을 덮어쓰지 않습니다.
-- 기존 DB는 02_migrate_existing.sql도 실행하세요.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS USERS (
    USER_ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    LOGIN_ID VARCHAR(50) NOT NULL,
    PASSWORD_HASH VARCHAR(255) NOT NULL,
    NAME VARCHAR(100) NOT NULL,
    EMAIL VARCHAR(255) NULL,
    PHONE VARCHAR(30) NULL,
    ROLE ENUM('USER','COMPANY','STORE','ADMIN') NOT NULL DEFAULT 'USER',
    STATUS ENUM('ACTIVE','SUSPENDED','WITHDRAWN') NOT NULL DEFAULT 'ACTIVE',
    CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT UQ_USERS_LOGIN_ID UNIQUE (LOGIN_ID),
    CONSTRAINT UQ_USERS_EMAIL UNIQUE (EMAIL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS USER_INFO (
    USER_INFO_ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    USER_ID BIGINT UNSIGNED NOT NULL,
    NICKNAME VARCHAR(50) NOT NULL,
    BIRTH_DATE DATE NOT NULL,
    GENDER ENUM('M','F') NOT NULL,
    NATIONALITY ENUM('DOMESTIC','FOREIGN') NOT NULL,
    INTRODUCTION VARCHAR(1000) NULL,
    CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT UQ_USER_INFO_USER_ID UNIQUE (USER_ID),
    CONSTRAINT UQ_USER_INFO_NICKNAME UNIQUE (NICKNAME),
    CONSTRAINT FK_USER_INFO_USERS FOREIGN KEY (USER_ID) REFERENCES USERS(USER_ID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS COMPANY_INFO (
    COMPANY_INFO_ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    USER_ID BIGINT UNSIGNED NOT NULL,
    COMPANY_NAME VARCHAR(200) NOT NULL,
    BUSINESS_NUMBER VARCHAR(20) NOT NULL,
    ADDRESS VARCHAR(500) NOT NULL,
    LOGO_IMAGE VARCHAR(500) NULL,
    HOMEPAGE VARCHAR(500) NULL,
    INTRODUCTION VARCHAR(2000) NULL,
    VERIFICATION_STATUS ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',
    CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT UQ_COMPANY_INFO_USER_ID UNIQUE (USER_ID),
    CONSTRAINT UQ_COMPANY_BUSINESS_NUMBER UNIQUE (BUSINESS_NUMBER),
    CONSTRAINT FK_COMPANY_INFO_USERS FOREIGN KEY (USER_ID) REFERENCES USERS(USER_ID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS STORE_INFO (
    STORE_INFO_ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    USER_ID BIGINT UNSIGNED NOT NULL,
    STORE_NAME VARCHAR(255) NOT NULL,
    REPRESENTATIVE VARCHAR(100) NOT NULL,
    ADDRESS VARCHAR(500) NOT NULL,
    REGION VARCHAR(100) NULL,
    SERVICE_COUNTRY VARCHAR(100) NOT NULL,
    LATITUDE DECIMAL(10,7) NULL,
    LONGITUDE DECIMAL(10,7) NULL,
    HOMEPAGE VARCHAR(500) NULL,
    FAX VARCHAR(30) NULL,
    TELEGRAM VARCHAR(100) NULL,
    KAKAO_ID VARCHAR(100) NULL,
    KAKAO_OPENCHAT VARCHAR(500) NULL,
    SERVICE_PORTS TEXT NULL,
    SERVICE_DETAILS TEXT NULL,
    REMARKS TEXT NULL,
    LOGO_IMAGE VARCHAR(500) NULL,
    FEATURE_IMAGE VARCHAR(500) NULL,
    INTRODUCTION VARCHAR(1000) NULL,
    VERIFICATION_STATUS ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',
    CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT UQ_STORE_INFO_USER_ID UNIQUE (USER_ID),
    CONSTRAINT FK_STORE_INFO_USERS FOREIGN KEY (USER_ID) REFERENCES USERS(USER_ID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS COMPANY_VERIFICATION_DOCUMENT (
    DOCUMENT_ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    COMPANY_INFO_ID BIGINT UNSIGNED NOT NULL,
    DOCUMENT_TYPE ENUM('BUSINESS_LICENSE','BUSINESS_CERTIFICATE','OTHER') NOT NULL,
    FILE_NAME VARCHAR(255) NOT NULL,
    FILE_PATH VARCHAR(1000) NOT NULL,
    REVIEW_STATUS ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',
    REVIEW_COMMENT VARCHAR(1000) NULL,
    CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT FK_COMPANY_DOCUMENT_INFO FOREIGN KEY (COMPANY_INFO_ID) REFERENCES COMPANY_INFO(COMPANY_INFO_ID) ON DELETE CASCADE,
    INDEX IX_COMPANY_DOCUMENT_INFO (COMPANY_INFO_ID, CREATED_AT)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS STORE_VERIFICATION_DOCUMENT (
    DOCUMENT_ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    STORE_INFO_ID BIGINT UNSIGNED NOT NULL,
    DOCUMENT_TYPE ENUM('BUSINESS_LICENSE','BUSINESS_CERTIFICATE','OTHER') NOT NULL,
    FILE_NAME VARCHAR(255) NOT NULL,
    FILE_PATH VARCHAR(1000) NOT NULL,
    REVIEW_STATUS ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',
    REVIEW_COMMENT VARCHAR(1000) NULL,
    CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT FK_STORE_DOCUMENT_INFO FOREIGN KEY (STORE_INFO_ID) REFERENCES STORE_INFO(STORE_INFO_ID) ON DELETE CASCADE,
    INDEX IX_STORE_DOCUMENT_INFO (STORE_INFO_ID, CREATED_AT)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 커뮤니티 게시글. USER_ID는 작성자이며 일반/기업/업체 회원 모두 작성할 수 있습니다.
CREATE TABLE IF NOT EXISTS COMMUNITY (
    POST_ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    USER_ID BIGINT UNSIGNED NOT NULL,
    CATEGORY VARCHAR(40) NOT NULL,
    TITLE VARCHAR(200) NOT NULL,
    CONTENT MEDIUMTEXT NOT NULL,
    VIEW_COUNT INT UNSIGNED NOT NULL DEFAULT 0,
    COMMENT_COUNT INT UNSIGNED NOT NULL DEFAULT 0,
    LIKE_COUNT INT UNSIGNED NOT NULL DEFAULT 0,
    DISLIKE_COUNT INT UNSIGNED NOT NULL DEFAULT 0,
    IS_HOT TINYINT(1) NOT NULL DEFAULT 0,
    STATUS ENUM('ACTIVE','HIDDEN','DELETED') NOT NULL DEFAULT 'ACTIVE',
    SEED_KEY VARCHAR(50) NULL,
    CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT FK_COMMUNITY_USERS FOREIGN KEY (USER_ID) REFERENCES USERS(USER_ID) ON DELETE CASCADE,
    CONSTRAINT UQ_COMMUNITY_SEED_KEY UNIQUE (SEED_KEY),
    INDEX IX_COMMUNITY_LIST (STATUS, CREATED_AT),
    INDEX IX_COMMUNITY_CATEGORY (CATEGORY, STATUS, CREATED_AT)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS COMMUNITY_COMMENT (
    COMMENT_ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    POST_ID BIGINT UNSIGNED NOT NULL,
    USER_ID BIGINT UNSIGNED NOT NULL,
    CONTENT VARCHAR(2000) NOT NULL,
    STATUS ENUM('ACTIVE','DELETED') NOT NULL DEFAULT 'ACTIVE',
    SEED_KEY VARCHAR(50) NULL,
    CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT FK_COMMUNITY_COMMENT_POST FOREIGN KEY (POST_ID) REFERENCES COMMUNITY(POST_ID) ON DELETE CASCADE,
    CONSTRAINT FK_COMMUNITY_COMMENT_USERS FOREIGN KEY (USER_ID) REFERENCES USERS(USER_ID) ON DELETE CASCADE,
    CONSTRAINT UQ_COMMUNITY_COMMENT_SEED_KEY UNIQUE (SEED_KEY),
    INDEX IX_COMMUNITY_COMMENT_POST (POST_ID, STATUS, CREATED_AT)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 구인공고. 회사 상세정보는 COMPANY_INFO를 통해 연결합니다.
CREATE TABLE IF NOT EXISTS JOBS (
    JOB_ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    COMPANY_INFO_ID BIGINT UNSIGNED NOT NULL,
    TITLE VARCHAR(200) NOT NULL,
    POSITION_NAME VARCHAR(100) NOT NULL,
    VESSEL_TYPE VARCHAR(100) NULL,
    LOCATION VARCHAR(100) NOT NULL,
    SALARY VARCHAR(100) NULL,
    SALARY_VISIBLE TINYINT(1) NOT NULL DEFAULT 1,
    EXPERIENCE VARCHAR(200) NULL,
    EMPLOYMENT_TYPE VARCHAR(100) NULL,
    WORK_SCHEDULE VARCHAR(200) NULL,
    DUTIES TEXT NULL,
    REQUIREMENTS TEXT NULL,
    DESCRIPTION MEDIUMTEXT NOT NULL,
    RECRUITMENT_STEPS TEXT NULL,
    DEADLINE_DATE DATE NULL,
    IS_ALWAYS_OPEN TINYINT(1) NOT NULL DEFAULT 0,
    JOB_STATUS ENUM('OPEN','CLOSED','DRAFT') NOT NULL DEFAULT 'OPEN',
    VIEW_COUNT INT UNSIGNED NOT NULL DEFAULT 0,
    SEED_KEY VARCHAR(50) NULL,
    CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT FK_JOBS_COMPANY_INFO FOREIGN KEY (COMPANY_INFO_ID) REFERENCES COMPANY_INFO(COMPANY_INFO_ID) ON DELETE CASCADE,
    CONSTRAINT UQ_JOBS_SEED_KEY UNIQUE (SEED_KEY),
    INDEX IX_JOBS_LIST (JOB_STATUS, CREATED_AT),
    INDEX IX_JOBS_COMPANY (COMPANY_INFO_ID, JOB_STATUS)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------------------
-- ---------------------------------------------------------------------------------------
-- 기존 ROLE enum에 ADMIN이 빠져 있을 수 있으므로 관리자 역할을 포함합니다.
ALTER TABLE USERS MODIFY COLUMN ROLE ENUM('USER','COMPANY','STORE','ADMIN') NOT NULL DEFAULT 'USER';
-- 기존 DB에 적용할 컬럼 보완. MariaDB 지원 버전에서는 IF NOT EXISTS로 중복 실행해도 안전합니다.
ALTER TABLE USER_INFO ADD COLUMN IF NOT EXISTS INTRODUCTION VARCHAR(1000) NULL;
ALTER TABLE COMPANY_INFO ADD COLUMN IF NOT EXISTS HOMEPAGE VARCHAR(500) NULL;
ALTER TABLE COMPANY_INFO ADD COLUMN IF NOT EXISTS INTRODUCTION VARCHAR(2000) NULL;
ALTER TABLE STORE_INFO ADD COLUMN IF NOT EXISTS LOGO_IMAGE VARCHAR(500) NULL;
ALTER TABLE STORE_INFO ADD COLUMN IF NOT EXISTS FEATURE_IMAGE VARCHAR(500) NULL;
ALTER TABLE STORE_INFO ADD COLUMN IF NOT EXISTS INTRODUCTION VARCHAR(1000) NULL;


