INSERT IGNORE INTO COMMUNITY (USER_ID, CATEGORY, TITLE, CONTENT, VIEW_COUNT, COMMENT_COUNT, LIKE_COUNT, DISLIKE_COUNT, IS_HOT, STATUS, SEED_KEY, CREATED_AT) SELECT USER_ID, '승선후기', '첫 승선 6개월, 예비 항해사분들께 드리고 싶은 이야기', '안녕하세요. 올해 처음으로 벌크선에 승선해 6개월의 항해를 마치고 돌아왔습니다.\n처음에는 낯선 환경과 긴 당직 시간이 가장 걱정됐지만, 생활 리듬을 만들고 동료들과 자주 대화하면서 생각보다 빠르게 적응할 수 있었습니다. 승선을 준비 중이라면 체력 관리와 기본 영어 표현을 꾸준히 익혀두시길 추천합니다.\n궁금한 점이 있다면 댓글로 남겨주세요. 제가 경험한 범위 안에서 답변드리겠습니다.', 382, 24, 86, 3, 1, 'ACTIVE', 'demo-community-01', CURRENT_TIMESTAMP - INTERVAL 1 DAY FROM USERS WHERE LOGIN_ID='demo_user_1';
