-- 개발용 관리자 로그인
-- ID: admin / PW: password
-- 운영 환경에서는 반드시 삭제하거나 별도 강력한 비밀번호 해시로 교체하세요.
-- USERS.ROLE에 ADMIN을 저장하므로 별도 ADMIN_INFO 테이블은 필수가 아닙니다.

-- ---------------------------------------------------
-- company에 추가할 담당자들 table
CREATE TABLE IF NOT EXISTS COMPANY_RECRUITER (
    RECRUITER_ID BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    COMPANY_INFO_ID BIGINT UNSIGNED NOT NULL,
    NAME VARCHAR(50) NOT NULL,
    POSITION VARCHAR(50) NULL,
    PHONE VARCHAR(20) NOT NULL,
    EMAIL VARCHAR(100) NOT NULL,
    IS_PRIMARY TINYINT(1) NOT NULL DEFAULT 0,
    CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT FK_RECRUITER_COMPANY_INFO FOREIGN KEY (COMPANY_INFO_ID) REFERENCES COMPANY_INFO(COMPANY_INFO_ID) ON DELETE CASCADE,
    INDEX IX_RECRUITER_COMPANY (COMPANY_INFO_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

